    await requestedRef.set({impiantiCount:plantNumber,totalPlants:plantNumber,workItemsCount:workItems.length,impiantiFattiCount:donePlants,impiantiDaFareCount:plantNumber-donePlants,workItemsFattiCount:workDone,workItemsDaFareCount:workItems.length-workDone,completedSubtotal,subtotalCompleted:completedSubtotal,workItemsModelVersion:2,operationalModelSyncedAt:server(),...actor()},{merge:true});
