  async function verifyOperationalModel(expectedCount){const snapshot=await commRef().collection("impianti").get(),actualCount=snapshot.size,expected=Math.max(0,Number(expectedCount)||0);if(expected>0&&actualCount<expected)throw new Error(`Verifica non superata: nella lista operativa risultano ${actualCount} impianti su ${expected}.`);state.operationalPlants=snapshot.docs.map(d=>({id:d.id,...d.data()}));return actualCount;}
