  function joined(w){const row={...(state.plants.find(p=>p.id===w.impiantoId)||{}),...w},gps=coordinateDiagnosis(row);return {...row,latitudine:gps.valid?gps.latitude:row.latitudine,longitudine:gps.valid?gps.longitude:row.longitudine,...coordinateMeta(gps),coordinateProblem:gps.status!=="VALID"};}
