  function filtered(){const q=norm(document.querySelector("#impianti-management-search")?.value),f=document.querySelector("#impianti-status-filter")?.value||"all";return state.work.map(joined).map(r=>({r,k:q?rank(r,q):0})).filter(x=>x.k<99&&(!f||f==="all"||(f==="done"&&x.r.stato==="FATTO")||(f==="todo"&&x.r.stato==="DA FARE")||(f==="working"&&x.r.stato==="IN LAVORAZIONE")||(f==="suspended"&&x.r.stato==="SOSPESO")||(f==="without-price"&&num(x.r.prezzoRibassato)==null)||(f==="errors"&&(x.r.priceListLinkStatus==="MISSING"||hasCoordinateProblem(x.r)))||(f==="without-coordinates"&&!coordinateDiagnosis(x.r).valid))).sort((a,b)=>a.k-b.k||state.direction*String(a.r[state.sort]??"").localeCompare(String(b.r[state.sort]??""),"it",{numeric:true})).map(x=>x.r);}
